#include <bits/stdc++.h>
using namespace std;

int H, W, N;
string S, T;
map<tuple<int,int,int>, bool> memo;

pair<int,int> applyMove(int r, int c, char d) {
    if (d == 'U') r--;
    else if (d == 'D') r++;
    else if (d == 'L') c--;
    else if (d == 'R') c++;
    return {r, c};
}

bool onGrid(int r, int c) {
    return r >= 1 && r <= H && c >= 1 && c <= W;
}

// returns true if piece stays on grid (Aoki wins)
bool solve(int step, int r, int c) {
    if (step == N) return true;
    auto key = make_tuple(step, r, c);
    if (memo.count(key)) return memo[key];

    // Takahashi chooses: apply S[step] or not
    // Takahashi wants false (off grid), so he picks option minimizing "stays"
    // For each Takahashi choice, Aoki then picks best response

    bool takahashiCanWin = false;
    for (int tm = 0; tm <= 1; tm++) {
        int nr = r, nc = c;
        if (tm == 1) { auto [tr, tc] = applyMove(r, c, S[step]); nr = tr; nc = tc; }
        if (!onGrid(nr, nc)) { takahashiCanWin = true; break; }
        // Aoki chooses
        bool aokiCanSave = false;
        for (int am = 0; am <= 1; am++) {
            int ar = nr, ac = nc;
            if (am == 1) { auto [tr, tc] = applyMove(nr, nc, T[step]); ar = tr; ac = tc; }
            if (!onGrid(ar, ac)) continue; // Aoki won't choose this
            if (solve(step + 1, ar, ac)) { aokiCanSave = true; break; }
        }
        if (!aokiCanSave) { takahashiCanWin = true; break; }
    }

    return memo[key] = !takahashiCanWin;
}

