public class Main {
    static int H, W, N;
    static String tMoves, aMoves;
    static int[][][][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        N = sc.nextInt();
        int si = sc.nextInt() - 1;
        int sj = sc.nextInt() - 1;
        tMoves = sc.next();
        aMoves = sc.next();

        memo = new int[N+1][2][H][W];
        for (int[][][] a : memo)
            for (int[][] b : a)
                for (int[] c : b)
                    Arrays.fill(c, -1);

        boolean result = play(0, 0, si, sj);
        System.out.println(result ? "Yes" : "No");
    }

    static boolean play(int step, int turn, int i, int j) {
        if (i < 0 || i >= H || j < 0 || j >= W) return true; // already out
        if (step == N) return false; // stayed in all steps

        if (memo[step][turn][i][j] != -1)
            return memo[step][turn][i][j] == 1;

        boolean res;
        String moves = (turn == 0) ? tMoves : aMoves;
        char moveChar = moves.charAt(step);

        if (turn == 0) {
            // Takahashi: wants to go out
            // He can choose to move or skip
            boolean canGoOut = false;
            // option: move
            int ni = i, nj = j;
            if (moveChar == 'U') ni--;
            else if (moveChar == 'D') ni++;
            else if (moveChar == 'L') nj--;
            else if (moveChar == 'R') nj++;
            if (ni < 0 || ni >= H || nj < 0 || nj >= W) {
                canGoOut = true;
            } else {
                canGoOut = play(step + 1, 1, ni, nj);
            }
            // option: skip
            boolean skipResult = play(step + 1, 1, i, j);
            res = canGoOut || skipResult;
        } else {
            // Aoki: wants to stay in
            // He can choose to move or skip
            boolean best = true;
            // option: move
            int ni = i, nj = j;
            if (moveChar == 'U') ni--;
            else if (moveChar == 'D') ni++;
            else if (moveChar == 'L') nj--;
            else if (moveChar == 'R') nj++;
            if (ni < 0 || ni >= H || nj < 0 || nj >= W) {
                best = false;
            } else {
                best = play(step + 1, 0, ni, nj);
            }
            // option: skip
            boolean skipResult = play(step + 1, 0, i, j);
            res = best && skipResult; // both must keep it in for Aoki's success
        }

        memo[step][turn][i][j] = res ? 1 : 0;
        return res;
    }
}

