    static char[] S, T;
    // dp[r][c] = can Takahashi force off grid from step i, position (r,c)?
    // Process from step N-1 back to 0

    static int dr(char c) { return c=='U'?-1:c=='D'?1:0; }
    static int dc(char c) { return c=='L'?-1:c=='R'?1:0; }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt(); W = sc.nextInt();
        N = sc.nextInt();
        int R = sc.nextInt(); int C = sc.nextInt();
        S = new char[N]; T = new char[N];
        for(int i=0;i<N;i++) S[i] = sc.next().charAt(0);
        for(int i=0;i<N;i++) T[i] = sc.next().charAt(0);

        // dp[r][c]: Takahashi wins? (1-indexed positions)
        // After step N: piece is on grid -> Takahashi loses
        boolean[][] dp = new boolean[H+2][W+2]; // false = Aoki wins

        // Process steps in reverse
        for(int i = N-1; i >= 0; i--) {
            boolean[][] ndp = new boolean[H+2][W+2];
            for(int r=1;r<=H;r++) {
                for(int c=1;c<=W;c++) {
                    // Takahashi's turn: picks S[i] or nothing
                    // For each Takahashi choice, compute result after Aoki's turn
                    boolean tWins = false;
                    for(int tm=0;tm<=1;tm++) {
                        int nr = r + (tm==1?dr(S[i]):0);
                        int nc = c + (tm==1?dc(S[i]):0);
                        // If off grid after Takahashi's move
                        if(nr<1||nr>H||nc<1||nc>W) { tWins=true; break; }
                        // Aoki's turn: picks T[i] or nothing, wants Takahashi to lose
                        boolean aokiCanSave = false;
                        for(int am=0;am<=1;am++) {
                            int ar = nr + (am==1?dr(T[i]):0);
                            int ac = nc + (am==1?dc(T[i]):0);
                            if(ar<1||ar>H||ac<1||ac>W) continue; // off grid = Takahashi wins, Aoki won't pick
                            if(!dp[ar][ac]) { aokiCanSave=true; break; }
                        }
                        if(!aokiCanSave) tWins=true; // all Aoki moves lead to T winning
                    }
                    ndp[r][c] = tWins;
                }
            }
            dp = ndp;
        }
        System.out.println(dp[R][C] ? "No" : "Yes");
    }
}

