public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();
        int N = fs.nextInt();
        int sr = fs.nextInt() - 1;
        int sc = fs.nextInt() - 1;
        char[] S = fs.next().toCharArray();
        char[] T = fs.next().toCharArray();

        boolean okRow = survivesOneDimension(sr, H, S, T, 'U', 'D');
        boolean okCol = survivesOneDimension(sc, W, S, T, 'L', 'R');

        System.out.println(okRow && okCol ? "YES" : "NO");
    }

    // Check survivability on one axis independently.
    // neg = direction decreasing coordinate (U or L)
    // pos = direction increasing coordinate (D or R)
    static boolean survivesOneDimension(int start, int size, char[] S, char[] T, char neg, char pos) {
        int l = 0, r = size - 1; // possible positions that can still survive from this step onward

        for (int i = S.length - 1; i >= 0; i--) {
            // Reverse Aoki's move: he can expand the survivable interval
            if (T[i] == neg) {
                if (r < size - 1) r++;
            } else if (T[i] == pos) {
                if (l > 0) l--;
            }

            // Reverse Takahashi's move: he shrinks the survivable interval
            if (S[i] == neg) {
                l++;
            } else if (S[i] == pos) {
                r--;
            }

            if (l > r) return false;
        }

        return l <= start && start <= r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

