    from functools import lru_cache

    dirs = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    @lru_cache(None)
    def dfs(step, i, j):
        if i < 0 or i >= H or j < 0 or j >= W:
            # Already off grid — this can only happen if we just moved off.
            # For Takahashi it's win, for Aoki it's lose.
            return False  # piece off grid
        if step == N:
            return True  # survived all steps

        # Takahashi's turn (even steps)
        if step % 2 == 0:
            # Can skip move
            if dfs(step + 1, i, j):
                return True
            # Or make move from S[step]
            di, dj = dirs[S[step]]
            ni, nj = i + di, j + dj
            if ni < 0 or ni >= H or nj < 0 or nj >= W:
                # Moves off grid — Takahashi wins immediately
                return True
            else:
                return dfs(step + 1, ni, nj)
        else:
            # Aoki's turn
            # Can skip move
            if not dfs(step + 1, i, j):
                return False
            # Or make move from T[step]
            di, dj = dirs[T[step]]
            ni, nj = i + di, j + dj
            if ni < 0 or ni >= H or nj < 0 or nj >= W:
                # Moves off grid — Aoki loses
                return False
            else:
                return dfs(step + 1, ni, nj)

    result = dfs(0, si, sj)
    print("YES" if result else "NO")

