    A = input_data[idx]; idx+=1

    dirs = {'U': (-1,0), 'D': (1,0), 'L': (0,-1), 'R': (0,1)}

    def get_delta(ch):
        return dirs[ch]

    @lru_cache(maxsize=None)
    def can_remove(step, row, col):
        # Returns True if Takahashi can force piece off grid
        if step == N:
            return False  # Game over, piece still on grid

        td = get_delta(T[step])
        ad = get_delta(A[step])

        t_options = [(0,0), td]  # Takahashi's choices
        a_options = [(0,0), ad]  # Aoki's choices

        # Takahashi wants EXISTS t: FORALL a: result is True
        for t in t_options:
            all_true = True
            for a in a_options:
                nr = row + t[0] + a[0]
                nc = col + t[1] + a[1]
                if nr < 1 or nr > H or nc < 1 or nc > W:
                    # Off grid - Takahashi wins this outcome
                    pass
                else:
                    if not can_remove(step+1, nr, nc):
                        all_true = False
                        break
            if all_true:
                return True
        return False

    if can_remove(0, r, c):
        print("Yes")
    else:
        print("No")

